 public sealed class NativeCombatBurst:MaskableGraphic {
  public float Progress;public Color Tint;public bool Critical;
  public void Present(float progress,Color tint,bool critical){Progress=progress;Tint=tint;Critical=critical;SetVerticesDirty();}
  protected override void OnPopulateMesh(VertexHelper v){v.Clear();var t=Progress;var c=Tint;c.a=(1-t)*(1-t);var radius=12+52*t;NativeFxGeometry.Ring(v,Vector2.zero,radius,Mathf.Max(1,5*(1-t)),c,t*1.6f,.82f);var core=new Color(1,.97f,.8f,Mathf.Clamp01(1-t*4));NativeFxGeometry.Quad(v,new Vector2(-8,-8),new Vector2(-8,8),new Vector2(8,8),new Vector2(8,-8),core,core);for(var i=0;i<(Critical?12:7);i++){var a=i*2.39996f;var d=new Vector2(Mathf.Cos(a),Mathf.Sin(a));var start=d*(7+t*40);var end=d*(22+t*65);var clear=c;clear.a=0;NativeFxGeometry.Line(v,start,end,Mathf.Max(1,4*(1-t)),c,clear);}var slash=new Vector2(35*(1+t),24*(1+t));NativeFxGeometry.Line(v,-slash,slash,Mathf.Max(1,7*(1-t)),c,new Color(1,1,.8f,0));}
 }
 public sealed class NativeCombatFeedback:MonoBehaviour {
  sealed class Hit {public GameObject Root;public RectTransform Rect;public NativeCombatBurst Burst;public Text Text;public string Target;public Vector3 LastPosition;public float Started;public bool Critical;public Color Tint;public float Side;}
  readonly List<Hit> active=new List<Hit>();readonly Stack<Hit> pool=new Stack<Hit>();readonly HashSet<string> seen=new HashSet<string>();readonly Queue<string> order=new Queue<string>();readonly Dictionary<string,float> small=new Dictionary<string,float>();
  NativeVillageUi village;NativeCampView view;Canvas canvas;RectTransform root;Font font;string world="";long animalSequence;bool initialized;int serial;
  public int DamageCount{get;private set;}public string LastTarget{get;private set;}public float LastAmount{get;private set;}
  void Start(){village=GetComponent<NativeVillageUi>();view=GetComponent<NativeCampView>();var go=new GameObject("战斗命中与伤害",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(CanvasGroup));root=(RectTransform)go.transform;canvas=go.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=65;var scaler=go.GetComponent<CanvasScaler>();NativeUiScale.Configure(scaler);var group=go.GetComponent<CanvasGroup>();group.blocksRaycasts=false;group.interactable=false;root.anchorMin=Vector2.zero;root.anchorMax=Vector2.one;root.offsetMin=root.offsetMax=Vector2.zero;font=Resources.Load<Font>("Fonts/NotoSansCJKsc-Regular")??Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");}
  void Remember(string id){if(id==null||!seen.Add(id))return;order.Enqueue(id);while(order.Count>768)seen.Remove(order.Dequeue());}
  void Update(){if(root==null)return;var s=village?.Snapshot;var visible=village!=null&&village.VillageActive&&s!=null&&!NativeStartup.Active;root.gameObject.SetActive(visible);if(!visible)return;var id=(string)s["worldId"]??"";var events=s["events"] as JArray??new JArray();var ecology=s["ecology"]?["events"] as JArray??new JArray();
   if(world!=id){world=id;seen.Clear();order.Clear();small.Clear();animalSequence=0;initialized=false;foreach(var h in active){h.Root.SetActive(false);pool.Push(h);}active.Clear();}
   if(!initialized){foreach(var e in events)Remember((string)e["id"]);foreach(var e in ecology)animalSequence=Math.Max(animalSequence,(long?)e["id"]??0);initialized=true;}
   else {
    foreach(var e in ecology){var seq=(long?)e["id"]??0;if(seq<=animalSequence)continue;animalSequence=seq;if((string)e["kind"]!="animal.hit")continue;var target=(string)e["target"];var critical=events.Any(x=>(string)x["kind"]=="combat.attack"&&(string)x["facts"]?["targetId"]==target&&(bool?)x["facts"]?["critical"]==true&&Math.Abs(((double?)x["at"]??0)-((double?)e["at"]??0))<.2);Show(target,(float?)e["amount"]??0,critical,(string)e["actor"]=="environment");}
    foreach(var e in events){var eid=(string)e["id"];if(eid==null||seen.Contains(eid))continue;Remember(eid);var facts=e["facts"];var kind=(string)e["kind"];if(kind=="wildlife.human_hit")Show((string)e["participants"]?.First,(float?)facts?["amount"]??0,false,false);else if(kind=="combat.attack"&&(bool?)facts?["hit"]==true&&!((string)facts?["targetId"]??"").StartsWith("animal-",StringComparison.Ordinal))Show((string)facts?["targetId"],(float?)facts?["damage"]??0,(bool?)facts?["critical"]==true,false);}
   }
   var now=Time.unscaledTime;for(var i=active.Count-1;i>=0;i--){var h=active[i];var t=(now-h.Started)/1.05f;if(t>=1){h.Root.SetActive(false);pool.Push(h);active.RemoveAt(i);continue;}if(village.TryCombatFeedbackPosition(h.Target,out var p))h.LastPosition=p;var screen=view.viewCamera.WorldToScreenPoint(h.LastPosition);if(screen.z<=0){h.Root.SetActive(false);continue;}h.Root.SetActive(true);RectTransformUtility.ScreenPointToLocalPointInRectangle(root,screen,null,out var point);h.Rect.anchoredPosition=point;h.Burst.Present(Mathf.Clamp01(t/.7f),h.Tint,h.Critical);var punch=1+.45f*Mathf.Exp(-t*16)*Mathf.Sin(t*25);h.Text.rectTransform.localScale=Vector3.one*punch;h.Text.rectTransform.anchoredPosition=new Vector2(h.Side*(12+18*t),28+75*t-18*t*t);var tint=h.Tint;tint.a=Mathf.Clamp01((1-t)/.3f);h.Text.color=tint;}
  }
  void Show(string target,float amount,bool critical,bool environmental){if(string.IsNullOrEmpty(target)||amount<=0||float.IsNaN(amount)||!village.TryCombatFeedbackPosition(target,out var pos))return;if(amount<1){small.TryGetValue(target,out var pending);amount+=pending;if(amount<1){small[target]=amount;return;}small.Remove(target);}if(active.Count>=48)return;var screen=view.viewCamera.WorldToScreenPoint(pos);if(screen.z<=0||screen.x<0||screen.x>Screen.width||screen.y<0||screen.y>Screen.height)return;Hit h;if(pool.Count>0)h=pool.Pop();else{var go=new GameObject("受击反馈",typeof(RectTransform),typeof(NativeCombatBurst));go.transform.SetParent(root,false);var rect=(RectTransform)go.transform;rect.sizeDelta=new Vector2(180,180);var textGo=new GameObject("真实伤害",typeof(RectTransform),typeof(Text),typeof(Outline));textGo.transform.SetParent(go.transform,false);var text=textGo.GetComponent<Text>();text.font=font;text.fontSize=30;text.fontStyle=FontStyle.Bold;text.alignment=TextAnchor.MiddleCenter;text.raycastTarget=false;text.horizontalOverflow=HorizontalWrapMode.Overflow;text.rectTransform.sizeDelta=new Vector2(210,60);textGo.GetComponent<Outline>().effectColor=new Color(.09f,.025f,.015f,.95f);textGo.GetComponent<Outline>().effectDistance=new Vector2(2,-2);h=new Hit{Root=go,Rect=rect,Burst=go.GetComponent<NativeCombatBurst>(),Text=text};h.Burst.raycastTarget=false;}
   h.Target=target;h.LastPosition=pos;h.Started=Time.unscaledTime;h.Critical=critical;h.Side=(++serial%3)-1;h.Tint=environmental?new Color(.8f,.74f,.65f):critical?new Color(1,.78f,.24f):target==(string)village.Snapshot?["playerId"]?new Color(1,.24f,.16f):new Color(1,.52f,.23f);h.Text.text=(critical?"暴击 ":"")+"−"+(amount>=10?Mathf.RoundToInt(amount).ToString():amount.ToString("0.#"));h.Text.fontSize=critical?38:30;h.Root.SetActive(true);active.Add(h);DamageCount++;LastTarget=target;LastAmount=amount;
  }
  void OnDestroy(){if(root!=null)Destroy(root.gameObject);}
 }
 public sealed partial class NativeVillageUi {
  public bool TryCombatFeedbackPosition(string id,out Vector3 point){point=Vector3.zero;if(view==null)return false;Transform model=null;if(actors.TryGetValue(id,out var person)&&person!=null)model=person;else if(animalModels.TryGetValue(id,out var animal)&&animal!=null)model=animal.transform;if(model!=null&&model.gameObject.activeInHierarchy){point=model.position+Vector3.up*1.2f;var renderer=model.GetComponentInChildren<Renderer>();if(renderer!=null)point=renderer.bounds.center+Vector3.up*Mathf.Min(1,renderer.bounds.extents.y*.5f);return true;}return false;}
 }
